interface Summary {
  count: number
  mean: number
  median: number
  std: number
  min: number
  max: number
  baseline: number
  peak: number | null
}

interface NumericRow extends Summary {
  sensor: string
  visualization: string
  series: string
  unit: string
}

interface NumericStateRow {
  sensor: string
  visualization: string
  series: "Estado"
  state: string
}

interface MetricRow {
  sensor: string
  visualization: string
  metric: string
  value: number | string | null
  unit: string
}

function finite(values: Array<number | null | undefined>) {
  return values.filter(
    (value): value is number =>
      typeof value === "number" && Number.isFinite(value)
  )
}

function summarize(input: Array<number | null | undefined>): Summary | null {
  const values = finite(input)
  if (!values.length) return null
  const sorted = [...values].sort((a, b) => a - b)
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length
  const median =
    values.length % 2
      ? sorted[Math.floor(values.length / 2)]
      : (sorted[values.length / 2 - 1] + sorted[values.length / 2]) / 2
  const std =
    values.length > 1
      ? Math.sqrt(
          values.reduce((sum, value) => sum + (value - mean) ** 2, 0) /
            (values.length - 1)
        )
      : 0
  const baselineStart = Math.floor(sorted.length * 0.05)
  const baselineEnd = Math.max(
    baselineStart + 1,
    Math.ceil(sorted.length * 0.2)
  )
  const baselineSlice = sorted.slice(baselineStart, baselineEnd)
  const baseline =
    baselineSlice.reduce((sum, value) => sum + value, 0) / baselineSlice.length
  const max = sorted[sorted.length - 1]
  return {
    count: values.length,
    mean,
    median,
    std,
    min: sorted[0],
    max,
    baseline,
    peak: baseline === 0 ? null : ((max - baseline) / Math.abs(baseline)) * 100,
  }
}

function numericRow(
  sensor: string,
  visualization: string,
  series: string,
  unit: string,
  values: Array<number | null | undefined>
): NumericRow | null {
  const summary = summarize(values)
  return summary ? { sensor, visualization, series, unit, ...summary } : null
}

function numericStateRow(
  sensor: string,
  visualization: string,
  loading: boolean,
  error: string | null
): NumericStateRow {
  return {
    sensor,
    visualization,
    series: "Estado",
    state: loading
      ? "Cargando…"
      : error
        ? `No disponible: ${error}`
        : "Sin datos",
  }
}

function format(value: number | string | null, decimals = 3) {
  if (value == null) return "—"
  if (typeof value === "string") return value
  if (!Number.isFinite(value)) return "—"
  return value.toLocaleString("es-CO", { maximumFractionDigits: decimals })
}

function selectedState(
  selected: Set<VisualizationId>,
  id: VisualizationId,
  loading: boolean,
  error: string | null,
  hasData: boolean,
  visualization: string,
  sensor: string
): MetricRow | null {
  if (!selected.has(id) || hasData) return null
  return {
    sensor,
    visualization,
    metric: "Estado",
    value: loading
      ? "Cargando…"
      : error
        ? `No disponible: ${error}`
        : "Sin datos",
    unit: "",
  }
}

