import { useChartDragZoom, usePointerDragZoom, ZoomControls } from "../components/ChartDragZoom"
import { useZoomHistory } from "../hooks/useZoomHistory"
import {
  axisTickDecimals,
  formatAxisTick,
  normalizeZoomRange,
  sameZoomRange,
  zoomSpan,
  sliceEegPsd,
  sliceEegSpectrogram,
  type ZoomRange,
} from "../chartZoom"
import type {
  EegPsdData,
  EegSpectrogramData,
  FixationHistogramData,
} from "../types"
import { resolveClickedPoint } from "./chartInteraction"

export const EEG_CHANNEL_COLORS: Record<string, string> = {
  le: "#2563EB",
  f4: "#DC2626",
  c4: "#059669",
  p4: "#7C3AED",
  p3: "#EA580C",
  c3: "#65A30D",
  f3: "#BE123C",
}

export interface TemporalChartPoint {
  time: number
  sourceTime: number
  [key: string]: number
}

export interface TemporalSeries {
  key: string
  label: string
  color: string
  unit: string
  /** Optional stroke styling, e.g. faded raw EEG under its smoothed trace. */
  opacity?: number
  strokeWidth?: number
}

/** Zoom state a caller can own, so a card keeps its zoom across remounts. */
export type ZoomController = ReturnType<typeof useZoomHistory<ZoomRange>>

export interface TemporalPeak {
  kind: "min" | "max"
  series_key: string
  series_label: string
  value: number
  time_s: number
  unit: string
  color: string
  line_style: "dotted" | "dashed"
  label: string
}

interface TooltipPayloadEntry {
  value?: number
  name?: string
  color?: string
  payload?: TemporalChartPoint
}

function ChartTooltip({
  active,
  payload,
  label,
  series,
}: {
  active?: boolean
  payload?: TooltipPayloadEntry[]
  label?: number
  series: TemporalSeries[]
}) {
  if (!active || !payload?.length) return null
  // Aligned axes draw time since the stimulus onset; the recording's own
  // time stays readable next to it.
  const sourceTime = payload[0]?.payload?.sourceTime
  const showSource =
    typeof sourceTime === "number" &&
    Number.isFinite(sourceTime) &&
    Math.abs(sourceTime - Number(label ?? 0)) > 1e-6
  return (
    <div className="max-w-[280px] rounded-lg bg-gray-900 px-3 py-2 text-xs text-white shadow-lg">
      <p className="mb-1 font-semibold text-gray-300">
        {Number(label ?? 0).toFixed(2)} s
      </p>
      {showSource ? (
        <p className="-mt-1 mb-1 text-[11px] text-gray-400">
          Tiempo de la grabación: {sourceTime.toFixed(2)} s
        </p>
      ) : null}
      {payload.map((entry) => {
        const definition = series.find((item) => item.label === entry.name)
        return (
          <p
            key={`${entry.name}-${entry.color}`}
            className="flex items-center gap-2 py-0.5"
          >
            <span
              className="h-2 w-2 shrink-0 rounded-full"
              style={{ backgroundColor: entry.color }}
            />
            <span className="truncate">
              {entry.name}: {Number(entry.value).toFixed(3)}{" "}
              {definition?.unit ?? ""}
            </span>
          </p>
        )
      })}
    </div>
  )
}

